import { createHash } from "node:crypto";

/** A section in a projected Working Context recovery summary. */
export interface ContextPressureRecoverySection {
  readonly goals: readonly ContextPressureRecoveryItem[];
  readonly unfinishedWork: readonly ContextPressureRecoveryItem[];
  readonly dependencies: readonly ContextPressureRecoveryItem[];
  readonly recentEvidence: readonly ContextPressureRecoveryItem[];
}

/** One item retained in a recovery section. */
export interface ContextPressureRecoveryItem {
  readonly id: string;
  readonly value: unknown;
}

/** Counts and truncation state are emitted for every section and in aggregate. */
export interface ContextPressureRecoverySectionResult {
  readonly items: readonly ContextPressureRecoveryItem[];
  readonly kept: number;
  readonly dropped: number;
  readonly truncated: boolean;
}

/** The four deterministic sections projected from a Working Context snapshot. */
export interface ContextPressureRecoverySections {
  readonly goals: ContextPressureRecoverySectionResult;
  readonly unfinishedWork: ContextPressureRecoverySectionResult;
  readonly dependencies: ContextPressureRecoverySectionResult;
  readonly recentEvidence: ContextPressureRecoverySectionResult;
}

/** The result of a recovery projection. */
export interface ContextPressureRecoveryResult {
  readonly status: "recovered" | "unknown" | "depth-exceeded";
  readonly complete: false;
  readonly sections?: ContextPressureRecoverySections;
  readonly dropped: number;
  readonly kept: number;
  readonly truncated: boolean;
  readonly digest?: string;
  readonly reason?: "empty-snapshot" | "missing-snapshot" | "depth-exceeded";
}

/** Minimal snapshot shape accepted by the projector. */
export interface WorkingContextSnapshotLike {
  readonly goals?: unknown;
  readonly unfinishedWork?: unknown;
  readonly dependencies?: unknown;
  readonly recentEvidence?: unknown;
  readonly [key: string]: unknown;
}

export interface ContextPressureRecoveryOptions {
  /** Maximum permitted handoff-chain depth. */
  readonly maxDepth?: number;
  /** Maximum number of items retained in each section. */
  readonly maxItemsPerSection?: number;
}

const SECTION_KEYS = ["goals", "unfinishedWork", "dependencies", "recentEvidence"] as const;
type SectionKey = (typeof SECTION_KEYS)[number];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function canonical(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return JSON.stringify(String(value));
    return JSON.stringify(value);
  }
  if (typeof value === "boolean") return JSON.stringify(value);
  if (typeof value === "bigint") return JSON.stringify(value.toString());
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (isRecord(value)) {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(String(value));
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonical(value)).digest("hex");
}

function itemList(snapshot: Record<string, unknown>, key: SectionKey): unknown[] {
  const direct = snapshot[key];
  if (Array.isArray(direct)) return direct;
  if (isRecord(direct)) {
    const nested = direct.items;
    if (Array.isArray(nested)) return nested;
  }
  const aliases: Record<SectionKey, readonly string[]> = {
    goals: ["goal", "objectives", "targets"],
    unfinishedWork: ["unfinished", "unfinished_work", "unfinished-work", "openWork", "pendingWork"],
    dependencies: ["dependency", "deps", "blockers"],
    recentEvidence: ["evidence", "recent_evidence", "recent-evidence", "observations"]
  };
  for (const alias of aliases[key]) {
    const candidate = snapshot[alias];
    if (Array.isArray(candidate)) return candidate;
    if (isRecord(candidate) && Array.isArray(candidate.items)) return candidate.items;
  }
  return [];
}

function depthOf(snapshot: Record<string, unknown>): number {
  const candidates = [snapshot.depth, snapshot.handoffDepth, snapshot.handoff_depth];
  if (isRecord(snapshot.handoff)) candidates.push(snapshot.handoff.depth, snapshot.handoff.chainDepth, snapshot.handoff.chain_depth);
  if (isRecord(snapshot.metadata)) candidates.push(snapshot.metadata.depth, snapshot.metadata.handoffDepth);
  for (const candidate of candidates) {
    if (typeof candidate === "number" && Number.isFinite(candidate)) return Math.max(0, Math.trunc(candidate));
    if (typeof candidate === "string" && /^\d+$/.test(candidate)) return Number(candidate);
  }
  return 0;
}

function itemId(value: unknown, index: number): string {
  if (isRecord(value)) {
    const id = value.id ?? value.key ?? value.name;
    if (typeof id === "string" || typeof id === "number") return String(id);
  }
  return String(index);
}

function projectSection(snapshot: Record<string, unknown>, key: SectionKey, limit: number): ContextPressureRecoverySectionResult {
  const source = itemList(snapshot, key);
  const kept = source.slice(0, limit).map((value, index) => ({ id: itemId(value, index), value }));
  const dropped = Math.max(0, source.length - kept.length);
  return { items: kept, kept: kept.length, dropped, truncated: dropped > 0 };
}

function hasSnapshotContent(snapshot: Record<string, unknown>): boolean {
  return SECTION_KEYS.some((key) => itemList(snapshot, key).length > 0);
}

/**
 * Projects a bounded, deterministic recovery summary from a Working Context snapshot.
 *
 * The function is deliberately fail-closed: an over-depth chain is rejected before
 * any section is produced, and an empty snapshot is reported as unknown. It never
 * asserts that the underlying task is complete.
 */
export function recoverContextPressure(
  snapshot: WorkingContextSnapshotLike | null | undefined,
  options: ContextPressureRecoveryOptions = {}
): ContextPressureRecoveryResult {
  const maxDepth = Math.max(0, Math.trunc(options.maxDepth ?? 4));
  const maxItemsPerSection = Math.max(0, Math.trunc(options.maxItemsPerSection ?? 20));

  if (snapshot === null || snapshot === undefined) {
    return { status: "unknown", complete: false, dropped: 0, kept: 0, truncated: false, reason: "missing-snapshot" };
  }
  if (!isRecord(snapshot)) {
    return { status: "unknown", complete: false, dropped: 0, kept: 0, truncated: false, reason: "missing-snapshot" };
  }
  if (depthOf(snapshot) > maxDepth) {
    return { status: "depth-exceeded", complete: false, dropped: 0, kept: 0, truncated: false, reason: "depth-exceeded" };
  }
  if (!hasSnapshotContent(snapshot)) {
    return { status: "unknown", complete: false, dropped: 0, kept: 0, truncated: false, reason: "empty-snapshot" };
  }

  const sections = {
    goals: projectSection(snapshot, "goals", maxItemsPerSection),
    unfinishedWork: projectSection(snapshot, "unfinishedWork", maxItemsPerSection),
    dependencies: projectSection(snapshot, "dependencies", maxItemsPerSection),
    recentEvidence: projectSection(snapshot, "recentEvidence", maxItemsPerSection)
  } satisfies ContextPressureRecoverySections;
  const kept = Object.values(sections).reduce((sum, section) => sum + section.kept, 0);
  const dropped = Object.values(sections).reduce((sum, section) => sum + section.dropped, 0);
  const truncated = Object.values(sections).some((section) => section.truncated);
  const digest = digestOf({ sections, kept, dropped, truncated });
  return { status: "recovered", complete: false, sections, kept, dropped, truncated, digest };
}

export const recoverWorkingContext = recoverContextPressure;
export const projectWorkingContextSnapshot = recoverContextPressure;

export default recoverContextPressure;

