export interface ContextPressureRecoveryResult {
  readonly status: "recovered" | "unknown" | "depth-exceeded";
  readonly complete: false;
  readonly sections?: ContextPressureRecoverySections;
  readonly dropped: number;
  readonly kept: number;
  readonly truncated: boolean;
  readonly digest?: string;
  readonly reason?: "empty-snapshot" | "missing-snapshot" | "depth-exceeded";
