/** Minimal snapshot shape accepted by the projector. */
export interface WorkingContextSnapshotLike {
  readonly goals?: unknown;
  readonly unfinishedWork?: unknown;
  readonly dependencies?: unknown;
  readonly recentEvidence?: unknown;
  readonly [key: string]: unknown;
