  const candidates = [snapshot.depth, snapshot.handoffDepth, snapshot.handoff_depth];
  if (isRecord(snapshot.handoff)) candidates.push(snapshot.handoff.depth, snapshot.handoff.chainDepth, snapshot.handoff.chain_depth);
  if (isRecord(snapshot.metadata)) candidates.push(snapshot.metadata.depth, snapshot.metadata.handoffDepth);
